def f(v, fmt="%.4g"):
    if v is None: return "not measured"
    if isinstance(v, bool): return "yes" if v else "no"
    if isinstance(v, (int, float)):
        try: return fmt % v
        except Exception: return str(v)
    return str(v)
def shell_of_max(r):
    """shell edges of the holdout rho_u^max (std family) from the start file; sphere radius of the single-sphere maximum from the ledger."""
    try:
        S = torch.load(os.path.join(ROOT, r["zfile"]), map_location="cpu", weights_only=False)
        sd = S.get("spec_diag_holdout") or {}; ru = sd.get("rho_u") or []; ed = (sd.get("shells") or {}).get("edges") or []
        k = max(range(len(ru)), key=lambda i: (ru[i] if ru[i] is not None else -1)) if ru else None
        s1 = f"rho_u^max std in shell [{ed[k][0]:.3g}, {ed[k][1]:.3g})" if k is not None and ed else "not measured"
        rn = sd.get("rho_nl") or []
        kn = max(range(len(rn)), key=lambda i: (rn[i] if rn[i] is not None else -1)) if rn else None
        s2 = f"rho_nl^max in shell [{ed[kn][0]:.3g}, {ed[kn][1]:.3g})" if kn is not None and ed else "not measured"
        gram = ""
        gr = sd.get("gram") or {}
        if gr and ed:
            core = [i for i in range(len(ed)) if ed[i][1] <= 1.0 + 1e-12 and (gr.get("gamma") or [None] * len(ed))[i] is not None]
            gram = "; ".join(f"[{ed[i][0]:.3g},{ed[i][1]:.3g}) b/a {gr['b_rms_N'][i] / max(gr['a_rms_L'][i], 1e-300):.2f} gamma {gr['gamma'][i]:+.2f}" for i in core) or "not measured"
        return s1, s2, gram
    except Exception as e:
        return "not measured", "not measured", "not measured"
def esc(c):
    """FM1 (verifier 642ba2c8): a literal '|' inside a cell splits the table; escape it as '\\|' before joining"""
    return str(c).replace("|", "\\|")
def _mkrow(cells):
    return "| " + " | ".join(esc(c) for c in cells) + " |"
