    core = f"sigma_u^max {f(rl.get('sigma_u_max'))} std / {f(rl.get('sigma_u_max_half'))} half (core sets {f(rl.get('sigma_u_max_core'))}); a_max {f(rl.get('a_max'))} / {f(rl.get('a_max_half'))} (core sets {f(rl.get('a_max_core'))}); a_eff {f(rl.get('a_eff'))}, core resolved {f(rl.get('core_resolved'))}"
    rnl = f"{f(rl.get('rho_nl_max_holdout'))} std / {f(rl.get('rho_nl_max_holdout_half'))} half; single sphere rho_u {f(rl.get('sphere_rho_u_max'))} at r {f(rl.get('sphere_r_at_max'))}"
    s1, s2, gram = shell_of_max(rl)
    where = f"{s1}; {s2}"
    tf = rl.get("tau_F_by_m")
    if isinstance(tf, dict) and tf.get("m") is not None:
        pm = "; ".join(f"m={m}: tail {t:.3f}, generated {g:.3f}, ratio {ar:.2f}" for m, t, g, ar in zip(tf["m"], tf.get("tail_fraction", []), tf.get("generated_fraction", []), tf.get("amplitude_ratio", [])))
    else:
        pm = "not measured"
    tfs = f"tau_F {f(rl.get('tau_F_R8'))} (2^8 R0) / {f(rl.get('tau_F_R12'))} (2^12 R0); delta_G core {f(rl.get('delta_G_core'))} max {f(rl.get('delta_G_max'))}; per-mode (d49b: squared-norm fractions of the generated and imposed tail by abs(m), amplitude ratio generated/tail): " + pm
