    bal = f"E_ren {f(rl.get('E_ren'))}; H_tot/int|h| {f(rl.get('H_tot_over_abs'))}; core alignment {f(rl.get('core_alignment'))}; K_E ratio {f(rl.get('K_ratio_direct'))}; K_H ratio {f(rl.get('K_H_ratio_direct'))}; carried mismatch {f(rl.get('carried_mismatch_rel') if rl.get('carried_mismatch_rel') is not None else rl.get('G_carried_mismatch_rel'))}; sampled Q_sw {f(rl.get('Q_sw'))}; {('e_core_holdout ' + f(rl.get('e_core_holdout'))) if rl.get('e_core_holdout') is not None else ('e_core (training) ' + f(rl.get('e_core')))}, e_F {f(rl.get('e_F'))}"
